actions.action:
// Economic nexus established per Wayfair - filing required
// RI threshold: $100,000 in gross receipts or 200 transactions
// Apportionment will be calculated by tables 7000-7500

// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate state additions (RI-specific)
            double additions = 0.0;

            // RI requires addback of federal interest (U.S. obligations)
            // additions += revenue.federal_bond_interest;

            // RI requires addback of IRC 199A deduction (RI doesn't conform)
            // additions += result.section_199a_deduction;

            // RI requires addback of certain federal bonus depreciation
            // additions += result.federal_ri_bonus_depreciation_difference;

            // RI requires addback of certain IRC 163(j) interest deductions
            // additions += result.federal_ri_interest_limitation_difference;

            apportionment.state_additions = additions;

            // Calculate state subtractions (RI-specific)
            double subtractions = 0.0;

            // RI allows deduction for RI state and municipal bond interest
            // subtractions += revenue.ri_municipal_bond_interest;

            // RI allows deduction for certain capital gains on qualified RI investments
            // subtractions += result.ri_qualified_capital_gain;

            // RI NOL deduction (limited carryforward provisions)
            // subtractions += result.ri_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // RI uses 7% flat rate on apportioned net income
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract state credits (Historic Preservation, R&D, film, renewable energy, etc.)
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
